package com.pocketmusic.android;
import android.app.*;
import android.content.*;
import android.webkit.*;
import android.view.ViewGroup;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

public class ValidatedSessionTest {
 private Context c;private File root;private String prefs;private AccountMusic.Transport transport;private MusicLoginFlow.Validator validator;
 private String capturedCookie;
 private static final String COOKIE="SAPISID=synthetic-flow; __Secure-3PSID=synthetic-flow";
 @Before public void setup()throws Exception{Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();root=Files.createTempDirectory(app.getCacheDir().toPath(),"validated-session-").toFile();prefs="validated-session-"+UUID.randomUUID();c=new ContextWrapper(app){public File getNoBackupFilesDir(){return root;}public File getCacheDir(){return root;}public SharedPreferences getSharedPreferences(String n,int m){return super.getSharedPreferences(prefs,m);}};transport=AccountMusic.transport;validator=MusicLoginFlow.validator;MusicLoginFlow.validator=AccountMusic::verifyAccount;}
 @After public void cleanup(){AccountMusic.transport=transport;MusicLoginFlow.validator=validator;c.deleteSharedPreferences(prefs);File[] files=root.listFiles();if(files!=null)for(File file:files)file.delete();root.delete();}
 private SessionAuth candidate(){return SessionAuth.capture(COOKIE,"visitor-fixture","channelA||userA","2","1.fixture");}
 private String menu(){return "{actions:[{openPopupAction:{popup:{multiPageMenuRenderer:{header:{activeAccountHeaderRenderer:{accountName:{runs:[{text:'Fixture account'}]}}}}}}}]}";}
 private String home(){return "{responseContext:{mainAppWebResponseContext:{loggedOut:false}},contents:[{musicCarouselShelfRenderer:{contents:[{musicTwoRowItemRenderer:{title:{runs:[{text:'Fixture song'}]},navigationEndpoint:{watchEndpoint:{videoId:'abcdefghijk',watchEndpointMusicSupportedConfigs:{watchEndpointMusicConfig:{musicVideoType:'MUSIC_VIDEO_TYPE_ATV'}}}}}}]}}]}";}
 private void verification(){AccountMusic.transport=(process,path,cookie,auth,body,user,visitor,version)->{assertEquals("/youtubei/v1/account/account_menu?prettyPrint=false",path);assertEquals("2",user);assertEquals("visitor-fixture",visitor);assertEquals("channelA",new JSONObject(body).getJSONObject("context").getJSONObject("user").getString("onBehalfOfUser"));assertTrue(auth.startsWith("SAPISIDHASH "));return menu();};}
 @Test public void realWebViewCaptureValidatesPersistsReloadsAndUsesSelectedAccountInFeed()throws Exception{
  String configured=webConfig("https://music.youtube.com/");assertTrue(capturedCookie.contains("__Secure-3PSID"));SessionAuth captured=MusicLoginFlow.capture(capturedCookie,configured);assertEquals("visitor-fixture",captured.visitorData);assertEquals("channelA",captured.dataSyncId);verification();SessionAuth connected=MusicLoginFlow.connect(c,captured,"test-connect",()->false);assertEquals("Fixture account",connected.accountName);assertTrue(connected.sameIdentity(YouTubeSession.read(c)));assertTrue(YouTubeSession.label(c).contains("Fixture account"));
  String disk=new String(Files.readAllBytes(new File(root,"youtube-session.bin").toPath()),StandardCharsets.ISO_8859_1);assertFalse(disk.contains("visitor-fixture"));assertFalse(disk.contains("synthetic-flow"));assertFalse(disk.contains("Fixture account"));
  AccountMusic.transport=(process,path,cookie,auth,body,user,visitor,version)->{assertTrue(path.startsWith("/youtubei/v1/browse"));assertEquals("2",user);assertEquals("visitor-fixture",visitor);JSONObject context=new JSONObject(body).getJSONObject("context");assertEquals("channelA",context.getJSONObject("user").getString("onBehalfOfUser"));assertEquals("visitor-fixture",context.getJSONObject("client").getString("visitorData"));return home();};assertEquals("abcdefghijk",AccountMusic.load(c,"test-feed").get(0).tracks.get(0).id);
  File lease=YouTubeSession.lease(c);try{String text=new String(Files.readAllBytes(lease.toPath()),StandardCharsets.UTF_8);assertTrue(text.startsWith("# Netscape"));assertTrue(text.contains("synthetic-flow"));assertFalse(text.contains("Fixture account"));assertFalse(text.contains("visitor-fixture"));}finally{lease.delete();}
 }
 @Test public void failedValidationPreservesThePreviousEncryptedAccount()throws Exception{YouTubeSession.save(c,"SAPISID=synthetic-previous");String before=YouTubeSession.fingerprint(c);AccountMusic.transport=(p,path,cookie,auth,body,user,visitor,version)->{throw new IOException("Synthetic denial");};try{MusicLoginFlow.connect(c,candidate(),"test-denied",()->false);fail();}catch(IOException expected){}assertEquals(before,YouTubeSession.fingerprint(c));assertFalse(YouTubeSession.read(c).complete());}
 @Test public void cancellationAfterVerificationCannotReplaceTheSavedAccount()throws Exception{YouTubeSession.save(c,"SAPISID=synthetic-previous");String before=YouTubeSession.fingerprint(c);verification();try{MusicLoginFlow.connect(c,candidate(),"test-cancel",()->true);fail();}catch(InterruptedIOException expected){}assertEquals(before,YouTubeSession.fingerprint(c));}
 @Test public void genericLoggedInFlagIsNotEnoughToSaveAnAccount()throws Exception{AccountMusic.transport=(p,path,cookie,auth,body,user,visitor,version)->"{responseContext:{mainAppWebResponseContext:{loggedOut:false}}}";try{MusicLoginFlow.connect(c,candidate(),"test-no-identity",()->false);fail();}catch(IOException expected){}assertFalse(YouTubeSession.connected(c));}
 @Test public void legacyCookiesRemainReadableAndUpgradeOnlyAfterVerification()throws Exception{YouTubeSession.save(c,COOKIE);assertFalse(YouTubeSession.read(c).complete());File lease=YouTubeSession.lease(c);try{assertTrue(new String(Files.readAllBytes(lease.toPath()),StandardCharsets.UTF_8).contains("SAPISID"));}finally{lease.delete();}verification();MusicLoginFlow.connect(c,candidate(),"test-upgrade",()->false);assertEquals("2",YouTubeSession.read(c).authUser);assertEquals("Fixture account",YouTubeSession.read(c).accountName);}
 @Test public void foreignPageConfigCannotBeCaptured()throws Exception{String result=webConfig("https://accounts.google.com/");try{MusicLoginFlow.capture(COOKIE,result);fail();}catch(Exception expected){}assertFalse(YouTubeSession.connected(c));}
 @Test public void unverifiedIdentityCannotBeCommitted()throws Exception{try{YouTubeSession.save(c,candidate());fail();}catch(IOException expected){}assertFalse(YouTubeSession.connected(c));}
 private String webConfig(String origin)throws Exception{
  Instrumentation test=InstrumentationRegistry.getInstrumentation();Context app=test.getTargetContext();Assume.assumeFalse(YouTubeSession.connected(app));TestMusicFixtures.Snapshot snapshot=new TestMusicFixtures.Snapshot(app);Activity[] activity={null};WebView[] web={null};AtomicReference<String> result=new AtomicReference<>();AtomicBoolean injected=new AtomicBoolean();CountDownLatch complete=new CountDownLatch(1);
  try{TestMusicFixtures.seed(app,List.of(TestMusicFixtures.song("abcdefghijk","Fixture song","Fixture artist")));if(android.os.Build.VERSION.SDK_INT>=33)test.getUiAutomation().grantRuntimePermission(app.getPackageName(),android.Manifest.permission.POST_NOTIFICATIONS);activity[0]=test.startActivitySync(new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));test.runOnMainSync(()->{web[0]=new WebView(activity[0]);web[0].getSettings().setJavaScriptEnabled(true);web[0].setWebViewClient(new WebViewClient(){public void onPageFinished(WebView view,String url){capturedCookie=CookieManager.getInstance().getCookie("https://music.youtube.com/");view.evaluateJavascript(MusicLoginFlow.CONFIG_SCRIPT,value->{result.set(value);complete.countDown();});}});activity[0].addContentView(web[0],new ViewGroup.LayoutParams(-1,-1));CookieManager manager=CookieManager.getInstance();assertFalse("Do not overwrite a browser account",LoginPolicy.ready(manager.getCookie("https://music.youtube.com/")));injected.set(true);manager.setCookie("https://music.youtube.com/","SAPISID=synthetic-flow; Domain=.youtube.com; Path=/; Secure",first->manager.setCookie("https://music.youtube.com/","__Secure-3PSID=synthetic-flow; Domain=.youtube.com; Path=/; Secure; HttpOnly",second->web[0].loadDataWithBaseURL(origin,"<html><script>window.ytcfg={get:function(k){return {VISITOR_DATA:'visitor-fixture',DATASYNC_ID:'channelA||userA',SESSION_INDEX:2,INNERTUBE_CLIENT_VERSION:'1.fixture'}[k]}}</script>Fixture Music page</html>","text/html","UTF-8",null)));});assertTrue("WebView config callback timed out",complete.await(10,TimeUnit.SECONDS));return result.get();
  }finally{test.runOnMainSync(()->{if(injected.get()){CookieManager manager=CookieManager.getInstance();manager.setCookie("https://music.youtube.com/","SAPISID=; Domain=.youtube.com; Path=/; Secure; Max-Age=0");manager.setCookie("https://music.youtube.com/","__Secure-3PSID=; Domain=.youtube.com; Path=/; Secure; HttpOnly; Max-Age=0");manager.flush();}if(web[0]!=null){web[0].stopLoading();web[0].destroy();}if(activity[0]!=null)activity[0].finish();});test.waitForIdleSync();snapshot.restore();}
 }
}
